-- =============================================================================
-- Category split, part 1 of 2: create Medical and Bones, move the products.
-- GENERATED by scripts/gen-category-split-migration.mjs from src/lib/categorySplit.js.
-- Only the category of the "medical-bone-models" products changes. No product is
-- created, deleted, duplicated or edited otherwise (prices, names, photos,
-- stock, IDs, reviews and orders are untouched).
-- =============================================================================

-- Safe while the OLD website code is still live: every moved product keeps the
-- old slug as an extra category until part 2, so the old page keeps working.
begin;

-- 1. Exact backup of every product that is touched (for the rollback).
create table if not exists public.category_split_backup_20261106 (
  product_id uuid primary key,
  category text,
  category_id uuid,
  extra_categories text[],
  saved_at timestamptz not null default now()
);
alter table public.category_split_backup_20261106 enable row level security;
revoke all on public.category_split_backup_20261106 from public, anon, authenticated;
insert into public.category_split_backup_20261106 (product_id, category, category_id, extra_categories)
select id, category, category_id, extra_categories from public.products
where category = 'medical-bone-models' or 'medical-bone-models' = any(extra_categories)
on conflict (product_id) do nothing;   -- a re-run keeps the ORIGINAL state

-- The products this run touches (for the checks in step 5).
create temporary table _split_touched on commit drop as
select id from public.products where category = 'medical-bone-models' or 'medical-bone-models' = any(extra_categories);

-- 2. The two new categories (English + Bangla), active.
insert into public.categories (name, name_bn, slug, blurb, status, sort) values
  ('Medical', 'মেডিকেল', 'medical', 'Anatomy models, organ models and accessories for medical and dental students, doctors and clinics.', 'active', 1),
  ('Bones', 'হাড়', 'bones', 'Individual human bones, vertebrae, ribs, skull bones, complete bone sets and skeletons for study.', 'active', 1)
on conflict (slug) do nothing;
update public.categories set status = 'active' where slug in ('medical', 'bones');

-- 3. Main category: the listed products -> Medical, every other one -> Bones.
--    category_id follows when it pointed at the old category.
update public.products p set
  category = case when p.slug in ('dental-model-foldable', 'dental-tool-holder', 'digestive-system-model', 'doctor-key-ring', 'doctor-pen-holder', 'human-brain-with-stand', 'human-heart', 'human-heart-with-stand', 'human-lungs', 'skeleton-hand-bookstop', 'sthetocap-cover-combo-basic') then 'medical' else 'bones' end,
  category_id = case when p.category_id = (select id from public.categories where slug = 'medical-bone-models')
    then (select id from public.categories where slug = case when p.slug in ('dental-model-foldable', 'dental-tool-holder', 'digestive-system-model', 'doctor-key-ring', 'doctor-pen-holder', 'human-brain-with-stand', 'human-heart', 'human-heart-with-stand', 'human-lungs', 'skeleton-hand-bookstop', 'sthetocap-cover-combo-basic') then 'medical' else 'bones' end)
    else p.category_id end,
  -- old slug kept as an extra category until part 2 (old code keeps working)
  extra_categories = array_append(array_remove(coalesce(p.extra_categories, '{}'), 'medical-bone-models'), 'medical-bone-models')
where p.category = 'medical-bone-models';

-- 4. Products that had the old category only as an EXTRA one: same rule.
update public.products p set
  extra_categories = array_remove(array_remove(p.extra_categories, 'medical-bone-models'),
    case when p.slug in ('dental-model-foldable', 'dental-tool-holder', 'digestive-system-model', 'doctor-key-ring', 'doctor-pen-holder', 'human-brain-with-stand', 'human-heart', 'human-heart-with-stand', 'human-lungs', 'skeleton-hand-bookstop', 'sthetocap-cover-combo-basic') then 'medical' else 'bones' end)
    || array[case when p.slug in ('dental-model-foldable', 'dental-tool-holder', 'digestive-system-model', 'doctor-key-ring', 'doctor-pen-holder', 'human-brain-with-stand', 'human-heart', 'human-heart-with-stand', 'human-lungs', 'skeleton-hand-bookstop', 'sthetocap-cover-combo-basic') then 'medical' else 'bones' end, 'medical-bone-models']
where p.category <> 'medical-bone-models' and 'medical-bone-models' = any(p.extra_categories)
  and p.category not in ('medical', 'bones');

-- 5. Checks: stop (and undo everything above) if anything is off.
do $$
declare moved int; med int; bon int; backed int; dup int;
begin
  select count(*) into backed from _split_touched t where exists (select 1 from public.category_split_backup_20261106 b where b.product_id = t.id);
  select count(*) into moved from public.products p join _split_touched t on t.id = p.id where p.category in ('medical', 'bones') or p.extra_categories && array['medical', 'bones'];
  select count(*) into med from public.products where category = 'medical';
  select count(*) into bon from public.products where category = 'bones';
  select count(*) into dup from public.products where category in ('medical', 'bones') and category = any(extra_categories);
  if moved <> (select count(*) from _split_touched) or backed <> moved then raise exception 'split check: % touched, % backed up, % moved', (select count(*) from _split_touched), backed, moved; end if;
  if dup > 0 then raise exception 'split check: % products list their main category twice', dup; end if;
  if med <> 11 then raise exception 'split check: expected 11 Medical products, found %', med; end if;
  raise notice 'category split: % products moved (Medical %, Bones %)', moved, med, bon;
end $$;

commit;
